package com.techgenius.tvosmovix;

import android.graphics.*;import android.graphics.drawable.*;import android.view.*;import android.widget.*;import java.util.*;import java.util.concurrent.*;import org.json.*;
/** Hidden until the user moves down from the app dock. */
final class RecommendationsRow extends LinearLayout {
    private final MainActivity host;private final LinearLayout cards,charts;private final HorizontalScrollView scroll,chartScroll;private final ExecutorService io=Executors.newSingleThreadExecutor();private boolean loaded;
    RecommendationsRow(MainActivity a){super(a);host=a;setOrientation(VERTICAL);setPadding(a.dp(42),a.dp(16),a.dp(42),a.dp(12));setClipChildren(false);setClipToPadding(false);GradientDrawable panel=new GradientDrawable(GradientDrawable.Orientation.TOP_BOTTOM,new int[]{0xe6283445,0xd9151d29});panel.setCornerRadius(a.dp(24));panel.setStroke(a.dp(1),0x35ffffff);setBackground(panel);setElevation(a.dp(8));TextView h=header(a,"Что посмотреть сегодня",20);addView(h,new LayoutParams(-1,a.dp(30)));TextView sub=header(a,"Кинопоиск · Иви · Zona  •  подборки и премьеры",11);sub.setTextColor(0xffb9c7d8);addView(sub,new LayoutParams(-1,a.dp(22)));scroll=new HorizontalScrollView(a);scroll.setHorizontalScrollBarEnabled(false);cards=new LinearLayout(a);cards.setOrientation(HORIZONTAL);scroll.addView(cards);addView(scroll,new LayoutParams(-1,a.dp(125)));TextView ch=header(a,"Чарты и популярное",16);ch.setPadding(0,a.dp(8),0,0);addView(ch,new LayoutParams(-1,a.dp(34)));chartScroll=new HorizontalScrollView(a);chartScroll.setHorizontalScrollBarEnabled(false);charts=new LinearLayout(a);charts.setOrientation(HORIZONTAL);chartScroll.addView(charts);addView(chartScroll,new LayoutParams(-1,a.dp(125)));setFocusable(false);}
    private TextView header(MainActivity a,String s,float size){TextView h=new TextView(a);h.setText(s);h.setTextColor(Color.WHITE);h.setTextSize(size);h.setTypeface(Ui.font(a,"semibold"));return h;}
    void load(){if(loaded)return;loaded=true;io.execute(()->{try{List<Suggestions.Item> items=Suggestions.fetchRussianServices(host);host.runOnUiThread(()->populate(items));}catch(Exception ignored){}});}
    private void populate(List<Suggestions.Item> items){if(items==null||items.isEmpty()){TextView empty=new TextView(host);empty.setText("Рекомендации пока недоступны");empty.setTextColor(0xffd4deeb);empty.setTextSize(13);cards.addView(empty,new LinearLayout.LayoutParams(host.dp(560),host.dp(80)));return;}int n=0;for(Suggestions.Item it:items){String service=(n++%3==0?"Кинопоиск":(n%3==1?"Иви":"Zona"));addCard(cards,it,service);addCard(charts,it,"№"+n+" · "+service);} }
    private void addCard(LinearLayout row,Suggestions.Item it,String label){LinearLayout c=new LinearLayout(host);c.setOrientation(VERTICAL);c.setFocusable(true);c.setClickable(true);c.setPadding(5,5,5,5);GradientDrawable bg=new GradientDrawable();bg.setColor(0xe61b2635);bg.setCornerRadius(host.dp(14));bg.setStroke(host.dp(1),0x28ffffff);c.setBackground(bg);ImageView img=new ImageView(host);img.setScaleType(ImageView.ScaleType.CENTER_CROP);c.addView(img,new LinearLayout.LayoutParams(host.dp(210),host.dp(88)));TextView t=new TextView(host);t.setText(label+"  ·  "+it.title);t.setTextColor(Color.WHITE);t.setTextSize(11.5f);t.setSingleLine(true);t.setEllipsize(android.text.TextUtils.TruncateAt.END);c.addView(t,new LinearLayout.LayoutParams(host.dp(210),host.dp(25)));c.setOnClickListener(v->Suggestions.open(host,it));c.setOnFocusChangeListener((v,f)->{v.setBackground(f?focusBg():bg);v.animate().scaleX(f?1.045f:1f).scaleY(f?1.045f:1f).setDuration(140).start();});LinearLayout.LayoutParams cp=new LinearLayout.LayoutParams(host.dp(220),host.dp(122));cp.rightMargin=host.dp(10);row.addView(c,cp);final String url=it.backdrop;io.execute(()->{Bitmap b=Suggestions.image(host,url,"w300",240);if(b!=null)img.post(()->img.setImageBitmap(b));});}
    private GradientDrawable focusBg(){GradientDrawable d=new GradientDrawable();d.setColor(0xffedf3fb);d.setCornerRadius(host.dp(10));return d;}
    boolean focusFirst(){if(cards.getChildCount()==0){load();return false;}cards.getChildAt(0).requestFocus();return true;}
}
